  const [missingRecordRequests, setMissingRecordRequests] = useState<DbMissingRecordRequest[]>([]);
  const [missingRecordStatus, setMissingRecordStatus] = useState("Switch to Verify role for missing-record requests");
  const [passportMissingRecordRequests, setPassportMissingRecordRequests] = useState<DbMissingRecordRequest[]>([]);
  const [passportMissingRecordStatus, setPassportMissingRecordStatus] = useState("Sign in to review requested Passport records");
  const [registrationIntents, setRegistrationIntents] = useState<DbRegistrationIntent[]>([]);
  const [registrationIntentStatus, setRegistrationIntentStatus] = useState("Sign in to load registration intent rows");
  const [registrationCompletionReceipts, setRegistrationCompletionReceipts] = useState<DbRegistrationCompletionReceipt[]>([]);
  const [registrationCompletionStatus, setRegistrationCompletionStatus] = useState("Sign in to load registration completion receipts");
  const [authRecoveryReceipts, setAuthRecoveryReceipts] = useState<DbAuthRecoveryReceipt[]>([]);
  const [onboardingReceipts, setOnboardingReceipts] = useState<DbOnboardingWizardReceipt[]>([]);
  const [v1ReadinessReceipts, setV1ReadinessReceipts] = useState<DbV1LiveDatabaseReadinessReceipt[]>([]);
  const [v1PilotRouteRunReceipts, setV1PilotRouteRunReceipts] = useState<DbV1PilotRouteRunReceipt[]>([]);
  const [realDatabaseCompletionReceipts, setRealDatabaseCompletionReceipts] = useState<DbRealDatabaseCompletionReceipt[]>([]);
  const [v1ReadinessStatus, setV1ReadinessStatus] = useState("Sign in to record V1 live database readiness receipts");
  const [serverSyncMonitor, setServerSyncMonitor] = useState<ServerSyncMonitorState>({
    status: "checking",
    headline: "Checking saved build",
    detail: "Looking for the release stamp on the current host.",
    checkedAt: null,
    commit: null,
    bundleMarker: null,
    source: "current_host",
    stampUrl: "/trustgraph-release.json"
  });
  const accountUser = accountContext ? accountContextToSessionUser(accountContext) : sessionUser;
  const organizationList = accountContext ? accountContextOrganizations(accountContext) : organizations;
  const activeMembership =
    accountUser.memberships.find((membership) => membership.id === activeMembershipId) ?? getActiveMembership(accountUser);
  const activeRole = getRole(activeMembership.role);
  const activeOrganization = getOrganizationFromList(activeMembership.organizationId, organizationList);
  const workspace = workspaces.find((item) => item.id === workspaceId) ?? workspaces[0];
  const workspaceAllowed = canAccessWorkspace(activeMembership.role, workspace.id);
  const authStatus = authSession ? accountStatus : authModeLabel();
  const teamManagementReady = Boolean(
    authSession && accountContext && teamMembers.length && !memberStatus.toLowerCase().includes("failed")
  );

  useEffect(() => {
    let cancelled = false;
    const stampUrl =
      typeof window === "undefined"
        ? "/trustgraph-release.json"
        : new URL("/trustgraph-release.json", window.location.origin).toString();

    async function checkServerSync() {
      setServerSyncMonitor((current) => ({
        ...current,
        status: "checking",
        headline: "Checking saved build",
        detail: "Reading the release stamp from the current host.",
        stampUrl
      }));

      try {
        const response = await fetch(`${stampUrl}?checked=${Date.now()}`, {
          cache: "no-store",
          headers: { Accept: "application/json" }
        });
        const contentType = response.headers.get("content-type") ?? "";
        const body = await response.text();
        const checkedAt = new Date().toISOString();

        if (cancelled) return;

        if (!response.ok) {
          setServerSyncMonitor({
            status: "pages_bundle",
            headline: "Release stamp not served here",
            detail: "GitHub Pages can still be current, but the VPS saved-build check needs the server updater.",
            checkedAt,
            commit: null,
            bundleMarker: null,
            source: "http_status",
            stampUrl
          });
          return;
        }

        if (!contentType.includes("application/json") || body.trim().startsWith("<!DOCTYPE html")) {
          setServerSyncMonitor({
            status: "needs_update",
            headline: "VPS needs the GitHub updater",
            detail: "The host is alive, but the release stamp returned the app shell instead of commit JSON.",
            checkedAt,
            commit: null,
            bundleMarker: null,
            source: "html_instead_of_release_stamp",
            stampUrl
          });
          return;
        }

        const stamp = JSON.parse(body) as {
          bundle_marker?: string;
          commit?: string;
          commit_short?: string;
          short_commit?: string;
          source?: string;
          generated_at?: string;
          updated_at?: string;
        };
        const reportedCommit = stamp.commit_short ?? stamp.short_commit ?? stamp.commit ?? null;
        const reportedMarker = stamp.bundle_marker ?? null;
        const isBuildPlaceholder =
          !reportedCommit ||
          reportedCommit === "build" ||
          reportedCommit === "build-time-placeholder" ||
          stamp.commit === "build-time-placeholder" ||
          stamp.updated_at === "build-time-placeholder";

        if (isBuildPlaceholder) {
          setServerSyncMonitor({
            status: "pages_bundle",
            headline: "GitHub bundle stamp found; VPS save still needs proof",
            detail: `The stamp contains marker ${reportedMarker ?? "missing"}, but no saved VPS Git commit yet.`,
            checkedAt: stamp.updated_at && stamp.updated_at !== "build-time-placeholder" ? stamp.updated_at : checkedAt,
            commit: reportedCommit,
            bundleMarker: reportedMarker,
            source: stamp.source ?? "static_release_stamp",
            stampUrl
          });
          return;
        }

        setServerSyncMonitor({
          status: "synced",
          headline: "Saved build stamp found",
          detail: `Server reports commit ${reportedCommit} with marker ${reportedMarker ?? "missing"} from ${stamp.source ?? "GitHub main"}.`,
          checkedAt: stamp.updated_at ?? stamp.generated_at ?? checkedAt,
          commit: reportedCommit,
          bundleMarker: reportedMarker,
          source: stamp.source ?? "release_stamp",
          stampUrl
        });
      } catch (error) {
        if (cancelled) return;
        setServerSyncMonitor({
          status: "unreachable",
          headline: "Saved build check could not connect",
          detail: error instanceof Error ? error.message : "The release stamp request failed.",
          checkedAt: new Date().toISOString(),
          commit: null,
          bundleMarker: null,
          source: "fetch_error",
          stampUrl
        });
      }
    }

    void checkServerSync();

    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    const hadHostedAuthCallback = hasHostedAuthCallbackUrl();
    const authCallbackType = hostedAuthCallbackType();
    const initialCallbackProof = readHostedAuthCallbackProof(
      hadHostedAuthCallback ? "callback_detected" : "no_callback_detected",
      authCallbackType === "recovery"
    );

    Promise.resolve()
      .then(() => readSessionFromUrl())
      .then((callbackSession) => callbackSession ?? loadStoredSession())
      .then((storedSession) => {
        if (cancelled) return;
        setAuthSession(storedSession);
        if (storedSession) {
          setHostedCallbackProof(
            hadHostedAuthCallback
              ? {
                  ...initialCallbackProof,
                  status: "callback_session_accepted",
                  recovery_session_ready: authCallbackType === "recovery",
                  next_action:
                    authCallbackType === "recovery"
                      ? "Open Account and set a new password."
                      : "Continue into the dashboard and create the needed Passport or Corporate workspace."
                }
              : readHostedAuthCallbackProof("no_callback_detected")
          );
          setShowPublicSite(false);
          setAccountStatus(
            authCallbackType === "recovery"
              ? "Password recovery session connected; set a new password in Account."
              : hadHostedAuthCallback
                ? "Hosted email verification accepted; live session connected"
                : "Live session connected"
          );
        }
      })
      .catch((error) => {
        if (cancelled) return;
        setHostedCallbackProof(readHostedAuthCallbackProof("callback_error"));
        setAccountStatus(operatorErrorMessage(error, "Login again to reconnect live database access."));
      });

    return () => {
      cancelled = true;
    };
  }, []);

